begin;
select plan(31);
select has_table('public','material_preparation_lists','preparation list table exists');
select has_table('public','material_preparation_revisions','immutable revisions exist');
select ok(has_function_privilege('authenticated','public.save_material_preparation_revision(uuid,uuid,uuid,text,uuid[],jsonb,integer,uuid)','EXECUTE'),'authenticated uses restricted writer');
select ok(not has_function_privilege('anon','public.save_material_preparation_revision(uuid,uuid,uuid,text,uuid[],jsonb,integer,uuid)','EXECUTE'),'anon cannot write');
select ok(not has_table_privilege('authenticated','public.material_preparation_lists','INSERT'),'no browser table inserts');
select ok(not has_table_privilege('authenticated','public.material_preparation_revisions','UPDATE'),'no revision updates');

set local role postgres;
insert into public.projects(id,organization_id,name,project_type,status,created_by) values
 ('00000000-0000-4000-8000-000000001100','00000000-0000-4000-8000-000000000010','DEMO F9.8.1 projekt','roof_renovation','draft','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001101','00000000-0000-4000-8000-000000000010','DEMO F9.8.1 másik projekt','roof_renovation','draft','00000000-0000-4000-8000-000000000001');
insert into public.calculations(id,organization_id,project_id,calculator_type,display_name,status)
 values('00000000-0000-4000-8000-000000001102','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100','DEMO.material-preparation','DEMO lemezszükséglet','current');
insert into public.calculation_revisions(id,organization_id,calculation_id,revision_number,input_schema_version,calculator_implementation_version,validation_status,created_by)
 values('00000000-0000-4000-8000-000000001103','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001102',1,'DEMO-1','DEMO-1','demo','00000000-0000-4000-8000-000000000001');
update public.calculations set current_revision_id='00000000-0000-4000-8000-000000001103' where id='00000000-0000-4000-8000-000000001102';
insert into public.material_products(id,organization_id,category,name,status,data_provenance,created_by)
 values('00000000-0000-4000-8000-000000001104','00000000-0000-4000-8000-000000000010','sheet_metal','DEMO lemez','active','demo','00000000-0000-4000-8000-000000000001');
insert into public.material_variants(id,organization_id,product_id,name,purchasing_unit,length_mm,nominal_width_mm,thickness_mm,technical_specs,data_provenance,created_by)
 values('00000000-0000-4000-8000-000000001105','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001104','DEMO 0,5 mm','piece',4000,125,0.5,'{"szin":"DEMO barna"}','demo','00000000-0000-4000-8000-000000000001');
insert into public.material_takeoffs(id,organization_id,project_id,source_calculation_id,source_calculation_revision_id,name,status,created_by) values
 ('00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100','00000000-0000-4000-8000-000000001102','00000000-0000-4000-8000-000000001103','DEMO A','draft','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100','00000000-0000-4000-8000-000000001102','00000000-0000-4000-8000-000000001103','DEMO B','draft','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001112','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100','00000000-0000-4000-8000-000000001102','00000000-0000-4000-8000-000000001103','DEMO másik hossz','draft','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001113','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100','00000000-0000-4000-8000-000000001102','00000000-0000-4000-8000-000000001103','DEMO előzetes','draft','00000000-0000-4000-8000-000000000001');
insert into public.material_takeoff_items(id,organization_id,takeoff_id,variant_id,estimation_method,measurement_source,final_quantity,quantity_unit,material_snapshot,data_provenance,created_by) values
 ('00000000-0000-4000-8000-000000001120','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001105','manual','DEMO A','2','piece','{"productId":"00000000-0000-4000-8000-000000001104","name":"DEMO 0,5 mm","lengthMm":4000,"nominalWidthMm":125,"thicknessMm":0.5,"technicalSpecs":{"szin":"DEMO barna"},"provenance":"demo"}','demo','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001121','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001105','manual','DEMO B','3','piece','{"productId":"00000000-0000-4000-8000-000000001104","name":"DEMO 0,5 mm","lengthMm":4000,"nominalWidthMm":125,"thicknessMm":0.5,"technicalSpecs":{"szin":"DEMO barna"},"provenance":"demo"}','demo','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001122','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001112','00000000-0000-4000-8000-000000001105','manual','DEMO eltérő lemez','4','piece','{"productId":"00000000-0000-4000-8000-000000001104","name":"DEMO 0,5 mm","lengthMm":5000,"nominalWidthMm":125,"thicknessMm":0.5,"technicalSpecs":{"szin":"DEMO barna"},"provenance":"demo"}','demo','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000001123','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001113','00000000-0000-4000-8000-000000001105','manual','DEMO draft','1','piece','{"productId":"00000000-0000-4000-8000-000000001104","name":"DEMO 0,5 mm","lengthMm":4000,"nominalWidthMm":125,"thicknessMm":0.5,"technicalSpecs":{"szin":"DEMO barna"},"provenance":"demo"}','demo','00000000-0000-4000-8000-000000000001');
update public.material_takeoffs set status='approved',approved_by='00000000-0000-4000-8000-000000000001',approved_at=now(),version=version+1
 where id in ('00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112');
select set_config('test.preparation_items','[{"id":"00000000-0000-4000-8000-000000001130","sourceItemIds":["00000000-0000-4000-8000-000000001120","00000000-0000-4000-8000-000000001121"],"category":"purchasing","status":"required","description":"DEMO tetőlemez"},{"id":"00000000-0000-4000-8000-000000001131","sourceItemIds":["00000000-0000-4000-8000-000000001122"],"category":"workshop","status":"prepare","description":"DEMO hosszú lemez"},{"id":"00000000-0000-4000-8000-000000001132","sourceItemIds":[],"category":"workshop","status":"prepare","description":"DEMO kézi szegély","quantity":"2.5","unit":"piece","manualTechnicalData":{"profileDescription":"DEMO hajtott elem","lengthMm":"1200","materialSpec":"DEMO lemez"}}]',true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('test.preparation_list_id',r.list_id::text,true) from public.save_material_preparation_revision(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',null,'DEMO tetőfelújítás',
 array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112']::uuid[],
 current_setting('test.preparation_items')::jsonb,0,'00000000-0000-4000-8000-000000001140') r;

select is((select preparation_state from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),'ready','approved source creates a procurement-ready list');
select is((select items_snapshot #>> '{0,quantity}' from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),'5.000000','compatible quantities are summed exactly');
select is((select items_snapshot #>> '{0,dimensions,lengthMm}' from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),'4000','sheet length is retained');
select is((select jsonb_array_length(items_snapshot #> '{0,sourceItemIds}') from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),2,'both source item IDs are retained');
select is((select count(*)::int from jsonb_array_elements((select items_snapshot from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1)) e where e->>'quantity'='4.000000' and e #>> '{dimensions,lengthMm}'='5000'),1,'different sheet length remains separate');
select is((select items_snapshot #>> '{2,kind}' from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),'manual','manual item has explicit provenance');
select is((select items_snapshot #>> '{2,dimensions,profileDescription}' from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),'DEMO hajtott elem','manual technical data is preserved');
select is((select version from public.material_preparation_lists where id=current_setting('test.preparation_list_id')::uuid),1,'initial version is one');
select is((select list_id::text from public.save_material_preparation_revision(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',null,'DEMO tetőfelújítás',
 array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112']::uuid[],
 current_setting('test.preparation_items')::jsonb,0,'00000000-0000-4000-8000-000000001140')),current_setting('test.preparation_list_id'),'create retry returns the same list');
select is((select count(*)::int from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid),1,'create retry does not duplicate revision');
select throws_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',null,'DEMO más név',array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112']::uuid[],current_setting('test.preparation_items')::jsonb,0,'00000000-0000-4000-8000-000000001140')$$,'40001',null,'changed create payload is rejected');
select lives_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',current_setting('test.preparation_list_id')::uuid,'DEMO tetőfelújítás',array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112']::uuid[],replace(current_setting('test.preparation_items'),'"required"','"ordered"')::jsonb,1,'00000000-0000-4000-8000-000000001141')$$,'manual status change appends a revision');
select is((select version from public.material_preparation_lists where id=current_setting('test.preparation_list_id')::uuid),2,'successful save advances version');
select is((select count(*)::int from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid),2,'old revisions remain available');
select is((select items_snapshot #>> '{0,status}' from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=1),'required','history preserves previous status');
select is((select items_snapshot #>> '{0,status}' from public.material_preparation_revisions where list_id=current_setting('test.preparation_list_id')::uuid and revision_number=2),'ordered','new status survives in revision 2');
select throws_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',current_setting('test.preparation_list_id')::uuid,'DEMO tetőfelújítás',array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112']::uuid[],replace(current_setting('test.preparation_items'),'"required"','"prepared"')::jsonb,1,'00000000-0000-4000-8000-000000001142')$$,'40001',null,'stale expected version is rejected');
select throws_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',current_setting('test.preparation_list_id')::uuid,'DEMO tetőfelújítás',array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001112']::uuid[],'[{"id":"00000000-0000-4000-8000-000000001133","sourceItemIds":["00000000-0000-4000-8000-000000001120","00000000-0000-4000-8000-000000001122"],"category":"purchasing","status":"required","description":"DEMO inkompatibilis"},{"id":"00000000-0000-4000-8000-000000001134","sourceItemIds":["00000000-0000-4000-8000-000000001121"],"category":"workshop","status":"prepare","description":"DEMO külön"}]'::jsonb,2,'00000000-0000-4000-8000-000000001143')$$,'22023',null,'incompatible sheet lengths cannot group');
select throws_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',current_setting('test.preparation_list_id')::uuid,'DEMO tetőfelújítás',array['00000000-0000-4000-8000-000000001110','00000000-0000-4000-8000-000000001111','00000000-0000-4000-8000-000000001112']::uuid[],'[{"id":"00000000-0000-4000-8000-000000001133","sourceItemIds":["00000000-0000-4000-8000-000000001120"],"category":"purchasing","status":"required","description":"DEMO duplikátum"},{"id":"00000000-0000-4000-8000-000000001134","sourceItemIds":["00000000-0000-4000-8000-000000001120","00000000-0000-4000-8000-000000001121"],"category":"workshop","status":"prepare","description":"DEMO ismételt"},{"id":"00000000-0000-4000-8000-000000001135","sourceItemIds":["00000000-0000-4000-8000-000000001122"],"category":"workshop","status":"prepare","description":"DEMO hosszú"}]'::jsonb,2,'00000000-0000-4000-8000-000000001144')$$,'22023',null,'duplicate source identity is rejected');
select set_config('test.preliminary_list_id',r.list_id::text,true) from public.save_material_preparation_revision(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',null,'DEMO előzetes',array['00000000-0000-4000-8000-000000001113']::uuid[],
 '[{"id":"00000000-0000-4000-8000-000000001150","sourceItemIds":["00000000-0000-4000-8000-000000001123"],"category":"workshop","status":"prepare","description":"DEMO előzetes tétel"}]'::jsonb,0,'00000000-0000-4000-8000-000000001151') r;
select is((select preparation_state from public.material_preparation_revisions where list_id=current_setting('test.preliminary_list_id')::uuid),'preliminary','draft source is marked preliminary');
select is((select status::text from public.material_takeoffs where id='00000000-0000-4000-8000-000000001113'),'draft','preparation does not auto-approve a source');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select throws_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001100',null,'DEMO jogosulatlan',array[]::uuid[],'[{"id":"00000000-0000-4000-8000-000000001160","sourceItemIds":[],"category":"workshop","status":"prepare","description":"DEMO kézi","quantity":"1","unit":"piece"}]'::jsonb,0,'00000000-0000-4000-8000-000000001161')$$,'42501',null,'nonmember cannot create lists');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='material_preparation_lists' and policyname='material_preparation_lists_select_member' and roles @> array['authenticated']::name[]),'RLS policy limits list reads to authenticated organization members');
select throws_ok($$select * from public.save_material_preparation_revision('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000001101',null,'DEMO másik projekt',array[]::uuid[],'[{"id":"00000000-0000-4000-8000-000000001170","sourceItemIds":[],"category":"workshop","status":"prepare","description":"DEMO kézi","quantity":"1","unit":"piece"}]'::jsonb,0,'00000000-0000-4000-8000-000000001171')$$,'42501',null,'project boundary is enforced');
reset role;
select throws_ok($$update public.material_preparation_revisions set items_snapshot='[]'::jsonb where list_id=current_setting('test.preparation_list_id')::uuid$$,'P0001',null,'immutable source history cannot be rewritten');
select * from finish();
rollback;
